 * Subscribes a handler to an event and returns an unsubscribe function.
 */
export function subscribe(
  emitter: EventEmitter,
  event: string,
  handler: Listener
): () => void {
  emitter.on(event, handler);

  return () => {
    emitter.off(event, handler);
  };
}

