 */
export function getConfigValue<K extends keyof AppConfig>(
  userConfig: Partial<AppConfig>,
  key: K
): AppConfig[K] {
  return (userConfig[key] !== undefined ? userConfig[key] : DEFAULTS[key]) as AppConfig[K];
}

